import{c as t,Z as e,Q as i,j as r,m as l,o as s}from"./chunks/framework.DOi4mjdC.js";const m=JSON.parse('{"title":"虞美人·春花秋月何时了","description":"","frontmatter":{"title":"虞美人·春花秋月何时了","author":"李煜","dynasty":"南唐"},"headers":[],"relativePath":"books/shici/songci/5.md","filePath":"books/shici/songci/5.md"}'),n={name:"books/shici/songci/5.md"};function h(u,a,c,p,d,q){const o=e("PoemNav");return i(),r("div",null,[a[0]||(a[0]=l('<h1 id="虞美人·春花秋月何时了" tabindex="-1">虞美人·春花秋月何时了 <a class="header-anchor" href="#虞美人·春花秋月何时了" aria-label="Permalink to &quot;虞美人·春花秋月何时了&quot;">​</a></h1><p><strong>[南唐] <a href="/authors/liyu.html">李煜</a></strong></p><h2 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h2><p>春花秋月何时了？往事知多少。小楼昨夜又东风，故国不堪回首月明中。</p><p>雕栏玉砌应犹在，只是朱颜改。问君能有几多愁？恰似一江春水向东流。</p><h2 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to &quot;注释&quot;">​</a></h2><ul><li>了：了结，完结</li><li>往事：指在南唐当皇帝时的生活</li><li>小楼：指词人被囚禁的住所</li><li>东风：春风</li><li>故国：指南唐</li><li>雕栏玉砌：雕花的栏杆和玉石的台阶，代指故国的宫殿</li><li>朱颜：红润的容颜，也指南唐旧人</li><li>君：词人自称</li></ul><h2 id="译文" tabindex="-1">译文 <a class="header-anchor" href="#译文" aria-label="Permalink to &quot;译文&quot;">​</a></h2><p>春花秋月的美好时光什么时候才能了结？往事又知道有多少！小楼昨夜又吹来了春风，在这明月之夜，实在不忍心回首故国。</p><p>故国宫殿里雕花的栏杆、玉石的台阶应该还在吧，只是人的容颜已经改变了。要问我心中有多少哀愁？就像那一江春水，滔滔不绝地向东流去。</p><h2 id="赏析" tabindex="-1">赏析 <a class="header-anchor" href="#赏析" aria-label="Permalink to &quot;赏析&quot;">​</a></h2><p>这首词是李煜的代表作，也是他的绝命词。李煜是南唐最后一位君主，亡国后被宋太宗囚禁于汴京。这首词通过今昔对比，抒发了亡国之君的深切哀愁。</p><p>上片以问起笔，&quot;春花秋月何时了&quot;，春花秋月本是美好的事物，但对亡国之君来说，却意味着岁月的流逝和无尽的折磨。&quot;往事知多少&quot;，概括了昔日帝王生活的种种。&quot;小楼昨夜又东风&quot;，春风又起，触发故国之思，&quot;不堪回首&quot;四字，写尽了内心的痛苦。</p><p>下片写故国景物依旧，而人事已非。&quot;雕栏玉砌应犹在，只是朱颜改&quot;，物是人非的感慨，是千古以来人们共同的情感体验。结尾&quot;问君能有几多愁？恰似一江春水向东流&quot;，以春水喻愁，将抽象的愁绪化为具体可感的形象，汪洋恣肆，奔流不息，成为写愁的千古名句。</p><p>全词语言自然流畅，情感真挚深沉，将帝王之悲与人生无常的感慨融为一体，具有极强的艺术感染力。据说宋太宗正是因这首词而赐毒酒将李煜毒死。</p><hr><h2 id="关于作者" tabindex="-1">关于作者 <a class="header-anchor" href="#关于作者" aria-label="Permalink to &quot;关于作者&quot;">​</a></h2><blockquote><p><strong>李煜</strong>（937年－978年），南唐最后一位国君，世称李后主。精书法、工绘画、通音律，尤以词名世，被称为“千古词帝”。</p><p><a href="/authors/liyu.html">查看作者详情 →</a></p></blockquote>',18)),s(o)])}const b=t(n,[["render",h]]);export{m as __pageData,b as default};
